import gc, itertools, os, sys
sys.path.insert(0, os.getcwd())
from src.resource import Rows
from src.service import stream_rows
from src.consumer import take

class RowsEx(Rows):
    def __init__(self, rows, read_error=None, close_error=None):
        super().__init__(rows)
        self.read_error = read_error
        self.close_error = close_error
    def read_next(self):
        self.reads += 1
        if self.read_error is not None:
            raise self.read_error
        if self.index == len(self.rows):
            return None
        v = self.rows[self.index]; self.index += 1
        return v
    def close(self):
        self.closes += 1
        if self.close_error is not None:
            raise self.close_error

FAILS = 0
def check(name, cond):
    global FAILS
    if not cond:
        FAILS += 1
        print("FAIL:", name)

for cleanup in (False, True):
    for exit_mode in ("exhaust", "close", "gc", "read_err", "transform_err"):
        C = RuntimeError("cleanup") if cleanup else None
        R = RuntimeError("read") if exit_mode == "read_err" else None
        rows = [] if exit_mode == "read_err" else [1, 2, 3]
        r = RowsEx(rows, read_error=R, close_error=C)
        def t(x, mode=exit_mode):
            if mode == "transform_err" and x == 2:
                raise ValueError("transform")
            return x * 2
        g = stream_rows(r, t)
        expected_closes = 1
        if exit_mode == "exhaust":
            out = list(g)
            check(f"exhaust out {cleanup}", out == [2, 4, 6])
        elif exit_mode == "close":
            next(g)
            try:
                g.close()
                check(f"close cleanup propagated {cleanup}", not cleanup)
            except RuntimeError as e:
                check(f"close cleanup propagated {cleanup}", cleanup and e is C)
        elif exit_mode == "gc":
            next(g)
            del g
            gc.collect()
        elif exit_mode == "read_err":
            try:
                next(g); check("read raised", False)
            except RuntimeError as e:
                check("read original", e is R)
        elif exit_mode == "transform_err":
            try:
                list(g); check("transform raised", False)
            except ValueError as e:
                check("transform original even with cleanup", str(e) == "transform")
            check(f"no further read after transform err {cleanup}", r.reads == 2)
        check(f"{exit_mode} cleanup={cleanup} closes==1", r.closes == expected_closes)

# take matrix
for limit in (0, 1, 2, 5):
    r = RowsEx([1, 2, 3, 4])
    out = take(r, lambda x: x + 1, limit)
    if limit <= 0:
        check(f"take {limit}", out == [] and r.reads == 0 and r.closes == 0)
    else:
        n = min(limit, 4)
        check(f"take {limit} out", out == [x + 1 for x in range(1, n + 1)])
        check(f"take {limit} reads", r.reads == (n if limit <= 4 else 5))
        check(f"take {limit} closes", r.closes == 1)

# take with transform failure on row 2 -> transform error, close once, reads == 2
r = RowsEx([1, 2, 3])
def bad(x):
    if x == 2: raise ValueError("boom")
    return x
try:
    take(r, bad, 3); check("take fail raised", False)
except ValueError:
    pass
check("take fail closes", (r.reads, r.closes) == (2, 1))

# take with read error and failing cleanup -> read error wins (generator suppresses cleanup)
R, C = KeyError("r"), RuntimeError("c")
r = RowsEx([], read_error=R, close_error=C)
try:
    take(r, lambda x: x, 3); check("take read raised", False)
except KeyError as e:
    check("take read original", e is R)
check("take read closes", r.closes == 1)

# two independent generators share no state; each closes once
r = RowsEx([1, 2])
g1, g2 = stream_rows(r, lambda x: x), stream_rows(r, lambda x: x)
list(g1); next(g2); g2.close()
check("two gens close once", r.closes == 1 or r.closes == 2)  # resource is shared; each gen closes it

print("FAILURES:", FAILS)
